      "angle": "先从通勤携带和外观选择切入，再讲内部小口袋、拉链主袋、长肩带与折叠，最后说规格和价格",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场互动",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天咱们聊一款日常好带的托特包。",
              "spoken_text": "欢迎来到直播间，今天咱们聊一款日常好带的托特包。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "平时上班、出门买东西，你更习惯手拎还是单肩背？",
              "spoken_text": "平时上班、出门买东西，你更习惯手拎还是单肩背？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "不同场合换包的麻烦",
          "sentences": [
            {
              "display_text": "有时候出门前会纠结：背大包显得太正式，拿小包又怕东西装不下。",
              "spoken_text": "有时候出门前会纠结：背大包显得太正式，拿小包又怕东西装不下。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "其实不用准备太多只包，选一个能应付上班、逛街、短途出行的款式，日常会省心不少。",
              "spoken_text": "其实不用准备太多只包，选一个能应付上班、逛街、短途出行的款式，日常会省心不少。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "这款是轻行可折叠通勤托特包，有黑色和米色两种颜色。",
              "spoken_text": "这款是轻行可折叠通勤托特包，有黑色和米色两种颜色。",
              "kind": "product_claim",
              "fact_ids": [
                "NAME",
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "颜色选择与日常搭配",
          "sentences": [
            {
              "display_text": "黑色和米色都是比较日常的颜色，黑色可以搭深色外套或牛仔裤，米色配浅色衬衫、针织衫看着更柔和。",
              "spoken_text": "黑色和米色都是比较日常的颜色，黑色可以搭深色外套或牛仔裤，米色配浅色衬衫、针织衫看着更柔和。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "如果你平时衣服颜色偏深，米色能提一点层次；如果衣柜里基础色多，黑色会更容易融入。",
              "spoken_text": "如果你平时衣服颜色偏深，米色能提一点层次；如果衣柜里基础色多，黑色会更容易融入。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "内部小口袋收纳",
          "sentences": [
            {
              "display_text": "包里面有一个小口袋，钥匙、门禁卡、耳机这类小东西可以单独放在这里。",
              "spoken_text": "包里面有一个小口袋，钥匙、门禁卡、耳机这类小东西可以单独放在这里。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "到公司或者回家开门时，不用在主袋里翻来翻去，手伸进去就能找到。",
              "spoken_text": "到公司或者回家开门时，不用在主袋里翻来翻去，手伸进去就能找到。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "主袋拉链开合",
          "sentences": [
            {
              "display_text": "主袋是拉链开合，上下班坐地铁或者公交时，把拉链拉上，包里的东西不容易散出来。",
              "spoken_text": "主袋是拉链开合，上下班坐地铁或者公交时，把拉链拉上，包里的东西不容易散出来。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "平时走路、骑车，拉链一拉，心里也踏实一些。",
              "spoken_text": "平时走路、骑车，拉链一拉，心里也踏实一些。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "长肩带与手提单肩两用",
          "sentences": [
            {
              "display_text": "它配的是长肩带，可以手提，也可以单肩背着。",
              "spoken_text": "它配的是长肩带，可以手提，也可以单肩背着。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "早上赶时间，拎起来就能出门；路上想腾出手回消息，换成单肩背也方便。",
              "spoken_text": "早上赶时间，拎起来就能出门；路上想腾出手回消息，换成单肩背也方便。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "可折叠与便携",
          "sentences": [
            {
              "display_text": "包身可以折叠，临时出门买东西或者周末短途出行，不想背大包的时候，把它折起来收着带着比较顺手。",
              "spoken_text": "包身可以折叠，临时出门买东西或者周末短途出行，不想背大包的时候，把它折起来收着带着比较顺手。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "不用的时候折起来放，不会占太多地方。",
              "spoken_text": "不用的时候折起来放，不会占太多地方。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
