        {
          "stage": "specification",
          "focus": "尺寸规格与颜色",
          "sentences": [
            {
              "display_text": "尺寸是三十八乘三十乘十二厘米，有黑色和米色两种颜色可选。",
              "spoken_text": "尺寸是三十八乘三十乘十二厘米，有黑色和米色两种颜色可选。",
