              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "你可以根据平时常穿的衣服颜色来挑，黑色和米色都是好搭配的。",
              "spoken_text": "你可以根据平时常穿的衣服颜色来挑，黑色和米色都是好搭配的。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "price",
          "focus": "价格说明",
          "sentences": [
            {
              "display_text": "这款包原价九十九元，现在活动价七十九元。",
              "spoken_text": "这款包原价九十九元，现在活动价七十九元。",
              "kind": "product_claim",
              "fact_ids": [
                "PRICE"
              ]
            }
          ]
        },
        {
          "stage": "promotion",
          "focus": "活动价",
          "sentences": [
            {
              "display_text": "活动价是七十九元，颜色选黑色还是米色，看你的日常搭配习惯就好。",
              "spoken_text": "活动价是七十九元，颜色选黑色还是米色，看你的日常搭配习惯就好。",
              "kind": "product_claim",
